css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-quotation,
.cd-quotation * { box-sizing: border-box; }
.cd-quotation { position: relative; width: 210mm; height: 297mm; overflow: hidden; color: #202020; background: #fff; font-family: "TH Sarabun Document", sans-serif; font-size: 4mm; line-height: 1.05; }
.cd-quotation .document-header { position: relative; height: 52mm; }
.cd-quotation .company-logo { position: absolute; top: 6mm; left: 9mm; width: 34mm; height: 15mm; object-fit: contain; }
.cd-quotation .company-info { position: absolute; top: 7mm; right: 8mm; width: 122mm; text-align: right; }
.cd-quotation .company-info strong { display: block; font-size: 4.5mm; }
.cd-quotation .company-info span { display: block; margin-top: 2mm; font-size: 3.4mm; }
.cd-quotation h1 { position: absolute; top: 31mm; left: 0; width: 100%; margin: 0; font-size: 6mm; text-align: center; }
.cd-quotation .document-number { position: absolute; top: 40.5mm; right: 7mm; width: 38mm; height: 9mm; padding-top: 2mm; border-radius: 3mm; background: #d4d4d4; text-align: center; }
.cd-quotation .customer-info { position: relative; display: grid; grid-template-columns: 56% 44%; width: 196mm; height: 42.5mm; margin: 0 7mm; overflow: hidden; border: 0.25mm solid #be3035; border-radius: 2.5mm; }
.cd-quotation .customer-panel, .cd-quotation .document-panel { position: relative; padding: 3mm 4mm; }
.cd-quotation .customer-panel { border-right: 0.25mm solid #be3035; }
.cd-quotation .customer-code { position: absolute; top: 3mm; right: 4mm; }
.cd-quotation .customer-address { margin-top: 3mm; font-size: 3.4mm; line-height: 1.2; }
.cd-quotation .document-panel dl, .cd-quotation .totals dl { display: grid; grid-template-columns: 39mm 1fr; margin: 0; }
.cd-quotation .document-panel dt, .cd-quotation .document-panel dd { min-height: 8mm; margin: 0; }
.cd-quotation .document-panel dd { font-size: 3.3mm; }
.cd-quotation .page-number { position: absolute; right: 4mm; bottom: 2mm; font-weight: 700; }
.cd-quotation .quotation-items { width: 196mm; margin: 5mm 7mm 0; }
.cd-quotation .introduction { height: 7mm; margin: 0 0 1mm 6mm; font-weight: 700; }
.cd-quotation table { width: 100%; height: 80mm; border-collapse: separate; border-spacing: 0; table-layout: fixed; border: 0.25mm solid #be3035; border-radius: 2.5mm 2.5mm 0 0; overflow: hidden; }
.cd-quotation th, .cd-quotation td { border-right: 0.25mm solid #be3035; }
.cd-quotation th:last-child, .cd-quotation td:last-child { border-right: 0; }
.cd-quotation th { height: 10mm; padding: 2mm 1mm; border-bottom: 0.25mm solid #be3035; background: #d4d4d4; font-weight: 700; text-align: center; }
.cd-quotation td { height: 7mm; padding: 1.3mm; vertical-align: top; }
.cd-quotation td:nth-child(1), .cd-quotation td:nth-child(3) { text-align: center; }
.cd-quotation td:nth-child(4), .cd-quotation td:nth-child(5) { text-align: right; }
.cd-quotation col.no { width: 6%; } .cd-quotation col.description { width: 50%; } .cd-quotation col.quantity { width: 15%; } .cd-quotation col.rate { width: 15%; } .cd-quotation col.amount { width: 14%; }
.cd-quotation .quotation-summary { display: grid; grid-template-columns: 56% 44%; width: 196mm; height: 94mm; margin: 0 7mm; border: 0.25mm solid #be3035; border-top: 0; border-radius: 0 0 2.5mm 2.5mm; }
.cd-quotation .remarks { padding: 3mm; border-right: 0.25mm solid #be3035; }
.cd-quotation .remarks > div { margin-top: 3mm; font-size: 3.4mm; }
.cd-quotation .totals { position: relative; }
.cd-quotation .totals dl { grid-template-columns: 49mm 1fr; height: 27mm; padding: 2mm 3mm; border-bottom: 0.25mm solid #be3035; }
.cd-quotation .totals dt, .cd-quotation .totals dd { margin: 0; min-height: 7mm; }
.cd-quotation .totals dd { text-align: right; }
.cd-quotation .amount-words { position: absolute; top: 27mm; width: 100%; height: 9mm; padding: 2mm; background: #d4d4d4; text-align: center; }
.cd-quotation .bank-info { position: absolute; top: 37mm; width: 100%; height: 24mm; padding: 3mm 5mm; line-height: 1.5; }
.cd-quotation .confidence { position: absolute; top: 63mm; width: 100%; text-align: center; }
.cd-quotation .sales-person { position: absolute; top: 74mm; width: 100%; text-align: center; }
.cd-quotation .signature-line { position: absolute; left: 18mm; right: 8mm; bottom: 10mm; border-bottom: 0.2mm dotted #555; }
.cd-quotation .signature-caption { position: absolute; bottom: 3mm; width: 100%; text-align: center; }
